ext="Total                                      R$ 2.500,00";textSize=20f;setTypeface(null,Typeface.BOLD);setTextColor(0xFFB78359.toInt());background=fbg(a,0xFFF6E7D6.toInt(),8);setPadding(fdp(a,14),fdp(a,18),fdp(a,14),fdp(a,18))},LinearLayout.LayoutParams(-1,-2).apply{topMargin=fdp(a,12)});c.addView(TextView(a).apply{text="Condições de pagamento";textSize=18f;setTypeface(null,Typeface.BOLD);setTextColor(0xFF2A3942.toInt());setPadding(0,fdp(a,25),0,fdp(a,15))});c.addView(TextView(a).apply{text="Entrada (50%)                                      R$ 1.250,00\nNa aprovação do orçamento\n\nSaldo (50%)                                      R$ 1.250,00\nNa entrega do serviço";textSize=14f;setTextColor(0xFF2A3942.toInt());background=fbg(a,Color.WHITE,13);setPadding(fdp(a,14),fdp(a,18),fdp(a,14),fdp(a,18))});s.addView(c);r.addView(s,LinearLayout.LayoutParams(-1,0,1f));val b=LinearLayout(a).apply{setPadding(fdp(a,20),fdp(a,8),fdp(a,20),fdp(a,18))};val x=Button(a).apply{text="Excluir";isAllCaps=false;setTextColor(0xFF2A3942.toInt());background=fbg(a,Color.WHITE,10)};val y=Button(a).apply{text="Enviar";isAllCaps=false;setTextColor(Color.WHITE);background=fbg(a,0xFF1A3443.toInt(),10);setOnClickListener{send()}};b.addView(x,LinearLayout.LayoutParams(0,fdp(a,52),1f));b.addView(y,LinearLayout.LayoutParams(0,fdp(a,52),1f).apply{leftMargin=fdp(a,12)});r.addView(b);a.setContentView(r)}}


